<script setup lang="ts">
import {ref,onMounted} from 'vue'
import {accountApi as api} from '../accountApi'
const config=ref<any>(null),orders=ref<any[]>([]),otp=ref(''),error=ref(''),message=ref(''),busy=ref(false),offset=ref(0),total=ref(0)
async function load(){const [c,o]=await Promise.all([api('/admin/billing/settings'),api('/admin/billing/orders?offset='+offset.value)]);config.value=c;orders.value=o.items;total.value=o.total}
async function save(){busy.value=true;error.value='';message.value='';try{await api('/admin/billing/settings','PUT',{ton_receiver:config.value.ton_receiver,prices:config.value.prices.map((p:any)=>({plan_id:p.plan_id,ton:p.ton,stars:Number(p.stars)}))},otp.value);message.value='Настройки приёма платежей сохранены.';await load()}catch(e:any){error.value=e.message}finally{busy.value=false;otp.value=''}}
onMounted(()=>load().catch(e=>error.value=e.message))
</script>
<template><section class="billing-settings"><h2>Настройки приёма платежей (TON & Telegram Stars)</h2><p>Реквизиты и цены меняются только с подтверждением текущим 2FA-кодом. Нулевая цена отключает способ оплаты. Новые ордера фиксируют реквизиты и цену; старые не изменяются.</p><p v-if="error" role="alert" class="error">{{error}}</p><p v-if="message" role="status">{{message}}</p><form v-if="config" @submit.prevent="save"><label>TON-адрес получателя (основная сеть)<input v-model="config.ton_receiver" maxlength="80" placeholder="EQ… / UQ… / 0:…" /></label><p>Telegram Stars: {{config.stars_configured?'бот настроен':'бот не настроен на VPS 1'}}. Секрет бота не передаётся на Витрину.</p><p v-if="config.ton_scanner">TON-проверка: {{config.ton_scanner.error||'работает'}} · {{config.ton_scanner.last_success_at||'нет успешных проверок'}}</p><div class="price-row" v-for="p in config.prices" :key="p.plan_id"><strong>{{p.title}} {{p.is_active?'':'(выключен)'}}</strong><label>Цена в TON<input v-model="p.ton" type="number" min="0" max="1000000" step="0.000000001" required /></label><label>Цена в ★ Stars<input v-model="p.stars" type="number" min="0" max="1000000" step="1" required /></label></div><label>Код 2FA или резервный код<input v-model="otp" autocomplete="one-time-code" maxlength="64" required /></label><button :disabled="busy">Сохранить платёжные настройки</button><router-link to="/account-security">Подключить 2FA администратора →</router-link></form><h3>Все входящие платежи · {{total}}</h3><div class="table-scroll"><table><thead><tr><th>Дата / Пользователь</th><th>Тариф</th><th>Сумма</th><th>Статус</th><th>Подтверждение</th></tr></thead><tbody><tr v-for="o in orders" :key="o.id"><td>{{new Date(o.created_at).toLocaleString()}}<small>{{o.user_id}}</small></td><td>{{o.plan_title}} · {{o.duration_days}} дн.</td><td>{{o.provider==='ton'?(Number(o.amount)/1e9)+' TON':'★ '+o.amount}}</td><td>{{o.status}}</td><td class="mono">{{o.provider_ref||'—'}}</td></tr><tr v-if="!orders.length"><td colspan="5">Платежей пока нет.</td></tr></tbody></table></div><div class="actions" v-if="total>50"><button :disabled="!offset" @click="offset-=50;load()">Назад</button><button :disabled="offset+50>=total" @click="offset+=50;load()">Далее</button></div></section></template>
<style scoped>.billing-settings{padding:24px;background:#151e2e;border:1px solid #344158;border-radius:14px;color:#e2e8f0;min-width:0}.billing-settings h2{font-size:21px;margin:0 0 16px}.billing-settings p{color:#a8b4c8;font-size:13px;line-height:1.7}.billing-settings label{display:block;font-size:13px;color:#c9d2e3;margin:16px 0}.billing-settings input{box-sizing:border-box;width:100%;padding:12px;margin-top:8px;background:#0d1422;border:1px solid #53617c;border-radius:8px;color:#fff;font:inherit}.price-row{display:grid;grid-template-columns:1.5fr 1fr 1fr;gap:20px;align-items:center;border-top:1px solid #344158;padding:10px 0}.billing-settings button{padding:12px 16px;border:0;border-radius:8px;background:#8276d7;color:#fff;cursor:pointer}.billing-settings a{display:inline-block;margin:14px;color:#bdb1ff}.billing-settings button:disabled{opacity:.5}.table-scroll{overflow:auto}.billing-settings table{width:100%;border-collapse:collapse;font-size:12px;text-align:left}.billing-settings td,.billing-settings th{border-bottom:1px solid #344158;padding:14px 12px}.billing-settings small{display:block;color:#8e9ab1;font-size:10px;margin-top:8px}.mono{font-family:monospace;max-width:200px;overflow-wrap:anywhere}.actions{display:flex;gap:10px;margin-top:14px}.billing-settings .error{color:#ffc0cf}@media(max-width:650px){.price-row{grid-template-columns:1fr 1fr;gap:10px}.price-row strong{grid-column:1/-1}.billing-settings{padding:18px}}
</style>
